<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Image Preview Delete Dialog</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #090b12;
        --panel: #111827;
        --panel-strong: #172033;
        --text: #f8fafc;
        --muted: #a7b0c0;
        --border: rgba(255, 255, 255, 0.12);
        --danger: #f43f5e;
        --danger-strong: #e11d48;
        --focus: #93c5fd;
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        display: grid;
        place-items: center;
        padding: 2rem;
        background:
          radial-gradient(circle at top left, rgba(244, 63, 94, 0.18), transparent 32rem),
          radial-gradient(circle at bottom right, rgba(59, 130, 246, 0.16), transparent 30rem),
          var(--bg);
        color: var(--text);
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      }

      main {
        width: min(100%, 44rem);
      }

      .preview-card {
        overflow: hidden;
        border: 1px solid var(--border);
        border-radius: 1.5rem;
        background: linear-gradient(145deg, rgba(17, 24, 39, 0.94), rgba(15, 23, 42, 0.78));
        box-shadow: 0 1.5rem 5rem rgba(0, 0, 0, 0.42);
      }

      .image-frame {
        margin: 0;
      }

      .image-frame img {
        display: block;
        width: 100%;
        aspect-ratio: 16 / 10;
        object-fit: cover;
        background: #0f172a;
      }

      .card-content {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        padding: 1.25rem;
      }

      h1,
      p {
        margin: 0;
      }

      h1 {
        font-size: clamp(1.35rem, 3vw, 2rem);
        letter-spacing: -0.04em;
      }

      .metadata {
        margin-top: 0.35rem;
        color: var(--muted);
        font-size: 0.95rem;
      }

      button {
        min-height: 2.75rem;
        border: 0;
        border-radius: 999px;
        padding: 0.75rem 1rem;
        color: var(--text);
        font: inherit;
        font-weight: 700;
        cursor: pointer;
      }

      button:focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 3px;
      }

      .trigger {
        background: linear-gradient(135deg, var(--danger), var(--danger-strong));
        box-shadow: 0 0.75rem 1.75rem rgba(225, 29, 72, 0.28);
      }

      .trigger:hover {
        filter: brightness(1.08);
      }

      .secondary-button {
        border: 1px solid var(--border);
        background: rgba(255, 255, 255, 0.08);
      }

      .secondary-button:hover {
        background: rgba(255, 255, 255, 0.13);
      }

      .danger-button {
        background: var(--danger-strong);
      }

      .danger-button:hover {
        background: #be123c;
      }

      dialog {
        width: min(calc(100vw - 2rem), 31rem);
        border: 1px solid var(--border);
        border-radius: 1.25rem;
        padding: 0;
        background: var(--panel);
        color: var(--text);
        box-shadow: 0 2rem 5rem rgba(0, 0, 0, 0.64);
      }

      dialog::backdrop {
        background: rgba(2, 6, 23, 0.78);
        backdrop-filter: blur(6px);
      }

      .dialog-content {
        padding: 1.5rem;
      }

      .dialog-header {
        display: flex;
        align-items: flex-start;
        gap: 1rem;
      }

      .warning-icon {
        display: grid;
        flex: 0 0 2.75rem;
        width: 2.75rem;
        height: 2.75rem;
        place-items: center;
        border-radius: 50%;
        background: rgba(244, 63, 94, 0.14);
        color: #fb7185;
        font-size: 1.5rem;
        font-weight: 900;
      }

      .dialog-title {
        font-size: 1.35rem;
        letter-spacing: -0.03em;
      }

      .dialog-description {
        margin-top: 0.5rem;
        color: var(--muted);
        line-height: 1.6;
      }

      .dialog-actions {
        display: flex;
        flex-wrap: wrap;
        justify-content: flex-end;
        gap: 0.75rem;
        margin-top: 1.5rem;
      }

      .status {
        margin-top: 1rem;
        color: #86efac;
        font-weight: 700;
      }

      @media (max-width: 34rem) {
        body {
          padding: 1rem;
        }

        .card-content,
        .dialog-actions {
          align-items: stretch;
          flex-direction: column;
        }

        button {
          width: 100%;
        }
      }
    </style>
  </head>
  <body>
    <main>
      <section class="preview-card" aria-labelledby="page-title">
        <figure class="image-frame">
          <img
            src="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1280 800'%3E%3Cdefs%3E%3ClinearGradient id='sky' x1='0' x2='1' y1='0' y2='1'%3E%3Cstop offset='0%25' stop-color='%232563eb'/%3E%3Cstop offset='52%25' stop-color='%237c3aed'/%3E%3Cstop offset='100%25' stop-color='%23f97316'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='1280' height='800' fill='url(%23sky)'/%3E%3Ccircle cx='1020' cy='180' r='86' fill='%23fde68a' opacity='.9'/%3E%3Cpath d='M0 610 270 360 500 590 710 430 1280 690v110H0z' fill='%230f172a' opacity='.88'/%3E%3Cpath d='M0 700 260 520 430 660 650 500 1280 730v70H0z' fill='%23111827'/%3E%3C/svg%3E"
            alt="A colorful mountain landscape at sunset"
          >
        </figure>
        <div class="card-content">
          <div>
            <h1 id="page-title">Sunset Ridge</h1>
            <p class="metadata">Image preview · Saved in your library</p>
          </div>
          <button class="trigger" type="button" aria-haspopup="dialog">Delete image</button>
        </div>
      </section>
      <p class="status" id="status" role="status" aria-live="polite"></p>
    </main>

    <dialog id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
      <div class="dialog-content">
        <div class="dialog-header">
          <div class="warning-icon" aria-hidden="true">!</div>
          <div>
            <h2 class="dialog-title" id="dialog-title">Delete this image?</h2>
            <p class="dialog-description" id="dialog-description">
              This will permanently remove “Sunset Ridge” from your library. This action cannot be undone.
            </p>
          </div>
        </div>
        <div class="dialog-actions">
          <button class="secondary-button" type="button" data-close-dialog>Cancel</button>
          <button class="danger-button" type="button" id="confirm-delete">Yes, delete image</button>
        </div>
      </div>
    </dialog>

    <script>
      const dialog = document.querySelector("#delete-dialog");
      const trigger = document.querySelector(".trigger");
      const cancelButton = document.querySelector("[data-close-dialog]");
      const confirmButton = document.querySelector("#confirm-delete");
      const previewCard = document.querySelector(".preview-card");
      const statusMessage = document.querySelector("#status");

      trigger.addEventListener("click", () => {
        dialog.showModal();
      });

      cancelButton.addEventListener("click", () => {
        dialog.close();
      });

      confirmButton.addEventListener("click", () => {
        dialog.close();
        previewCard.remove();
        statusMessage.textContent = "Sunset Ridge was deleted from your library.";
      });

      dialog.addEventListener("click", (event) => {
        if (event.target === dialog) {
          dialog.close();
        }
      });
    </script>
  </body>
</html>
